INSERT INTO public.voice_guide_texts (section_key, module_key, section_title, script) VALUES
('hebdo:creme-fraiche:1', 'hebdo', 'Crème fraîche', 'F suivi hebdomadaire dyal crème fraîche, khtar simana. Lkol nhar, ssejjel quantité, numéro de lot, couleur, riha ou texture. Zid visa dyal opérateur ou manager, ou dghya Enregistrer. Ila kayna chi anomalie, ma tst3melch produit ou 3lem lmas2oul.'),
('hebdo:mouvement-glaces:1', 'hebdo', 'Mouvement glaces', 'F mouvement glaces, khtar simana ou qelleb 3la parfum. Ssejjel stock initial, les entrées b numéro de lot, ou sorties dyal kol nhar. Raje3 quantités ou lots qbel ma tdir Enregistrer, bach stock restant ybqa s7i7.'),
('hebdo:mouvement-tartes:1', 'hebdo', 'Mouvement tartes', 'F mouvement tartes, khtar simana ou article. Ssejjel les entrées, les sorties ou numéro de lot f nhar s7i7. T2ekked men les quantités ou raje3 stock restant qbel ma tdir Enregistrer.'),
('hebdo:mouvement-produits-nettoyants:1', 'hebdo', 'Mouvement produits nettoyants', 'F mouvement produits nettoyants, khtar simana ou produit. Ssejjel dakchi li dkhel ou li tkhrej f nhar dyalo. Raje3 lquantité ou stock restant, ou ma tkhletch had produits m3a produits alimentaires.'),
('hebdo:suivi-materiel:1', 'hebdo', 'Suivi matériel', 'F suivi matériel, khtar simana ou qelleb 3la article. Ssejjel stock initial dyal simana, les entrées ou les sorties. Stock restant kayt7seb men stock initial zayed entrées naqes sorties. Melli tsali, dghya Enregistrer.'),
('hebdo:transferts-recus-envoyes:1', 'hebdo', 'Transferts reçus / envoyés', 'Bach tssejjel transfert, khtar wach reçu wella envoyé, date, provenance wella destination, article, quantité, ou chkon dar transfert. Zid numéro de lot ila kayn, ou dghya Ajouter le transfert. Raje3 détail ou total dyal transferts f liste. Ila rje3 article, sta3mel bouton Retour.')
